class Solution:
    def minLargest(self, nums1: list[int], nums2: list[int]) -> int:
        L1, L2 = len(nums1), len(nums2)
        L = L1 + L2
        def feasible(M):
            INF = M + 1
            nxt = [[INF] * (M + 2) for _ in range(2)]
            for t in range(M, 0, -1):
                nxt[0][t] = nxt[0][t + 1]
                nxt[1][t] = nxt[1][t + 1]
                nxt[t & 1][t] = t
            f = [[-1] * (L2 + 1) for _ in range(L1 + 1)]
            f[0][0] = 0
            for i in range(L1 + 1):
                for j in range(L2 + 1):
                    cur = f[i][j]
                    if cur < 0:
                        continue
                    if i < L1:
                        nt = nxt[nums1[i] & 1][cur + 1]
                        if nt <= M and (f[i + 1][j] < 0 or nt < f[i + 1][j]):
                            f[i + 1][j] = nt
                    if j < L2:
                        nt = nxt[nums2[j] & 1][cur + 1]
                        if nt <= M and (f[i][j + 1] < 0 or nt < f[i][j + 1]):
                            f[i][j + 1] = nt
            return f[L1][L2] >= 0
        M = L
        while not feasible(M):
            M += 1
        return M

